// Pictograms use fixed geometry so the same object stays recognizable across states.
function svgArt(body, name='', view='0 0 120 120', cls='pictogram') {
  return `<svg class="${cls}" viewBox="${view}" ${name?`role="img" aria-label="${name}"`:'aria-hidden="true"'} xmlns="http://www.w3.org/2000/svg">${body}</svg>`;
}
