function lampScene(on, {small=false}={}) {
  const rays=on?`<path d="M149 119L75 220H285L211 119Z" fill="#efd181" opacity=".48"/><ellipse cx="181" cy="224" rx="103" ry="14" fill="#e9c978" opacity=".5"/>`:'';
  return svgArt(`<rect x="0" y="0" width="360" height="260" rx="22" fill="${on?'#f3eedb':'#e6e9e1'}"/><path d="M35 230H325" stroke="#b6c2ae" stroke-width="3"/>${rays}<path d="M180 111V215M151 219H209" stroke="#4b6658" stroke-width="9" stroke-linecap="round"/><path d="M150 57H211L232 119H128Z" fill="${on?'#e9bc61':'#9aafa1'}" stroke="#486456" stroke-width="4"/><ellipse cx="180" cy="120" rx="42" ry="6" fill="${on?'#fae9a7':'#7e9587'}"/>${on?'<path d="M180 131V141" stroke="#f3d489" stroke-width="5" stroke-linecap="round"/>':''}`,on?'Luminária acesa, iluminando a mesa':'A mesma luminária apagada', '0 0 360 260',small?'scene-svg mini-scene':'scene-svg');
}
function plantScene(wet) {
  return svgArt(`<rect width="360" height="260" rx="22" fill="#edf0e5"/><path d="M42 229H318" stroke="#c0c9b6" stroke-width="3"/><path d="M181 165V78" stroke="#5c8059" stroke-width="6"/><path d="M180 116Q127 109 135 70Q182 69 180 116M184 96Q224 98 233 58Q188 51 184 96" fill="#8bad7d" stroke="#5c8059" stroke-width="3"/><path d="M133 161H228L214 225H146Z" fill="#c89372" stroke="#8c7459" stroke-width="3"/><ellipse cx="180" cy="163" rx="46" ry="9" fill="${wet?'#77644b':'#ab936a'}"/>${wet?'<path d="M150 159l7 4m22-7l7 4m18-3l5 4" stroke="#8bb9c5" stroke-width="4"/>':'<path d="M155 162l12 4 8-7 12 5 15-4" stroke="#766348" stroke-width="2" fill="none"/>'}`,wet?'A planta no vaso com a terra molhada':'A planta no mesmo vaso com a terra seca','0 0 360 260','scene-svg');
}
function basketScene(filled, count=1) {
  const fruit=(x,y)=>`<g transform="translate(${x} ${y}) scale(.45)"><path d="M16 40H104A44 44 0 0 1 16 40Z" fill="#dc776b" stroke="#52794f" stroke-width="7"/><path d="M44 50v6m16 2v6m17-14v6" stroke="#46452e" stroke-width="3"/></g>`;
  return svgArt(`<rect width="360" height="260" rx="22" fill="#f3eddf"/><path d="M29 221H331" stroke="#c9bda4" stroke-width="3"/>${!filled?fruit(56,170):''}<path d="M206 171Q247 87 289 171" fill="none" stroke="#897149" stroke-width="6"/>${filled?Array.from({length:count},(_,i)=>fruit(202+(i%2)*28,135-Math.floor(i/2)*23)).join(''):''}<path d="M191 172H306L294 219H203Z" fill="#c6a06b" stroke="#897149" stroke-width="3"/><path d="M198 189H302M201 204H297M219 174L225 217M247 174V218M275 174L270 217" stroke="#a57d4b" stroke-width="3"/>`,filled?'A melancia dentro da cesta':'Uma melancia na mesa e uma cesta vazia','0 0 360 260','scene-svg');
}
function cactusScene(raised){let figure=cactus();if(!raised)figure=figure.replace('M113 208H91c-28 0-39-15-39-40v-20c0-21 29-21 29 0v18c0 9 7 12 31 12M190 188h25c23 0 32-12 32-35v-17c0-20-29-20-29 0v15c0 9-7 10-28 10','M113 182H91c-28 0-39 15-39 40v10c0 21 29 21 29 0v-8c0-9 7-12 31-12M190 170h25c23 0 32 12 32 35v17c0 20-29 20-29 0v-15c0-9-7-10-28-10');return `<div class="cactus-scene ${raised?'raised':''}" role="img" aria-label="Caco com os braços ${raised?'levantados':'abaixados'}">${figure.replace('role="img"','aria-hidden="true"').replace(/aria-label="[^"]*"/,'')}</div>`;}
function weatherScene(rain){return svgArt(`<rect width="360" height="230" rx="20" fill="${rain?'#e5eceb':'#f1edda'}"/><path d="M0 186Q180 155 360 186V230H0Z" fill="#c2d1ac"/>${rain?'<path d="M114 81Q101 42 138 41Q167 11 194 45Q237 30 246 74Q260 99 224 100H127Q101 99 114 81Z" fill="#9aafb1"/><path d="M131 117l-7 15m43-15l-7 15m43-15l-7 15m-48 16l-7 15m43-15l-7 15" stroke="#7b9da9" stroke-width="5" stroke-linecap="round"/>':'<circle cx="180" cy="76" r="33" fill="#e4bc61"/><g stroke="#e4bc61" stroke-width="5" stroke-linecap="round"><path d="M180 24V13M180 128V139M128 76H116M232 76H244M143 39L134 30M217 39L226 30M143 113L134 122M217 113L226 122"/></g>'}`,rain?'Chuva caindo no jardim':'Dia de sol no jardim','0 0 360 230','scene-svg');}
function batteryScene(full){return svgArt(`<rect width="360" height="230" rx="20" fill="#e9ede3"/><rect x="81" y="63" width="189" height="103" rx="14" fill="#faf8ed" stroke="#4f6b5d" stroke-width="6"/><path d="M276 94h10v40h-10" fill="#4f6b5d"/>${Array.from({length:full?3:1},(_,i)=>`<rect x="${95+i*54}" y="77" width="${full?43:14}" height="75" rx="6" fill="${full?'#83a47c':'#ca8975'}"/>`).join('')}`,full?'Bateria cheia':'Bateria quase vazia','0 0 360 230','scene-svg');}
